/bin/bash -lc "python3 - <<'PY'
import os, shutil, zipfile, tempfile
import xml.etree.ElementTree as ET

ppt='/home/user/Desktop/43_1.pptx'
backup='/home/user/Desktop/43_1.pptx.bak-before-edit'
if not os.path.exists(backup):
    shutil.copy2(ppt, backup)

ET.register_namespace('a','http://schemas.openxmlformats.org/drawingml/2006/main')
ET.register_namespace('r','http://schemas.openxmlformats.org/officeDocument/2006/relationships')
ET.register_namespace('p','http://schemas.openxmlformats.org/presentationml/2006/main')
ET.register_namespace('p14','http://schemas.microsoft.com/office/powerpoint/2010/main')
ET.register_namespace('p15','http://schemas.microsoft.com/office/powerpoint/2012/main')
ET.register_namespace('mc','http://schemas.openxmlformats.org/markup-compatibility/2006')
ET.register_namespace('a14','http://schemas.microsoft.com/office/drawing/2010/main')

ns={
 'p':'http://schemas.openxmlformats.org/presentationml/2006/main',
 'a':'http://schemas.openxmlformats.org/drawingml/2006/main',
}
A='{%s}' % ns['a']

def underline_text_shapes(root):
    for sp in root.findall('.//p:sp', ns):
        if sp.find('.//a:t', ns) is None:
            continue
        for r in sp.findall('.//a:r', ns):
            rpr = r.find('a:rPr', ns)
            if rpr is None:
                rpr = ET.Element(A+'rPr')
                # rPr must precede t/br nodes within a:r
                r.insert(0, rpr)
            rpr.set('u', 'sng')
        for end in sp.findall('.//a:endParaRPr', ns):
            end.set('u', 'sng')
        for defr in sp.findall('.//a:defRPr', ns):
            defr.set('u', 'sng')

def move_pictures_to_top(root):
    for pic in root.findall('.//p:pic', ns):
        off = pic.find('.//a:off', ns)
        if off is not None:
            off.set('y', '0')

with zipfile.ZipFile(ppt, 'r') as zin:
    tmp_fd, tmp_path = tempfile.mkstemp(prefix='43_1_edit_', suffix='.pptx', dir='/home/user/Desktop')
    os.close(tmp_fd)
    with zipfile.ZipFile(tmp_path, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data = zin.read(item.filename)
            if item.filename in ('ppt/slides/slide1.xml', 'ppt/slides/slide2.xml'):
                root = ET.fromstring(data)
                underline_text_shapes(root)
                if item.filename == 'ppt/slides/slide2.xml':
                    move_pictures_to_top(root)
                data = ET.tostring(root, encoding='utf-8', xml_declaration=True)
            zout.writestr(item, data)
    os.replace(tmp_path, ppt)
print('patched', ppt)
print('backup', backup)
PY"

